# inspect components extracted using same BFS logic
from collections import deque
h,w=len(grid),len(grid[0]); seen=set(); comps=[]
for r in range(h):
 for c in range(w):
  if grid[r][c]==0 or (r,c) in seen: continue
  q=deque([(r,c)]); seen.add((r,c)); cells=[]
  while q:
   y,x=q.popleft();cells.append((y,x))
   for ny,nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
    if 0<=ny<h and 0<=nx<w and grid[ny][nx]!=0 and (ny,nx) not in seen: seen.add((ny,nx));q.append((ny,nx))
  comps.append((min(y for y,x in cells),max(y for y,x in cells),min(x for y,x in cells),max(x for y,x in cells),len(cells)))
print(comps)
